with valid as (select id, supplier_name, country, city, case when country in ('JP', 'UK') then 'Core' else 'Other' end as country_group, trim(city) as clean_city, coalesce(city, 'UNKNOWN') as city_clean from suppliers where city is null), base as (select *, case when city = 'Singapore' then 1 else 0 end as is_singapore from valid where supplier_name not like '%Trad%'), base_suppliers as (select *, upper(country) as country_upper, concat_ws(',', supplier_name, city) as supplier_name_city_key from base where is_singapore < 28) select id, supplier_name, country, city, country_group, is_singapore, supplier_name_city_key from base_suppliers order by id
